//! A clip's video and audio halves — Detach Audio and the two enablement
//! flags it sets, `set_enabled`.
//!
//! Cut out of `edit_clip.rs` under the size rule at grading L3, a pure move:
//! `edit_clip.rs` decides where a clip sits, this decides which of its halves
//! plays.

use crate::model::{AudioProps, Enabled, Project, Source};
use crate::outcome::Outcome;

impl Project {
    /// Splits the clip's audio onto its own clip on the track BELOW,
    /// inserting a track at index 0 when the clip is already on the bottom
    /// one (spec §6).
    ///
    /// The original keeps its video and gets `enabled.audio = false`; the
    /// new clip is `{video: false, audio: true}` with the same source, in
    /// point, duration and speed, and its VIDEO props, so re-enabling video
    /// on it is not lossy. The two name each other in `linked` (spec §11
    /// AU-90), and Attach Audio is the way back. Refuses, naming why, with
    /// no audio to detach (spec §11 #88), and when the new clip breaks the
    /// overlap rule below.
    pub fn detach_audio(&self, clip: u32) -> Result<Outcome, String> {
        let target = self.require_clip(clip)?.clone();
        let why = match target.source {
            Source::Media { media, .. } if !self.require_media(media)?.has_audio => {
                format!("media {media} has no audio track")
            }
            Source::Media { .. } if target.enabled.audio => String::new(),
            Source::Media { .. } => "its audio is switched off".to_string(),
            _ => "it is not a media clip".to_string(),
        };
        if !why.is_empty() {
            let why = format!("clip {clip} has no audio to detach: {why}");
            return Ok(Outcome::Refused(why));
        }
        let index = self.require_track_index(target.track)?;

        let mut next = self.clone();
        let below = match index.checked_sub(1).and_then(|i| self.tracks.get(i)) {
            Some(track) => track.id,
            None => {
                // The clip is on the bottom track, so the audio needs a new
                // one under it. Naming by the count keeps it unique without
                // renumbering the tracks above.
                let track = next.numbered_track();
                let id = track.id;
                next.tracks.insert(0, track);
                id
            }
        };

        let mut audio_clip = target.clone();
        // Actions move with the clip and need their own ids; a video action
        // on a non-drawing clip is inert, and dropping it would lose the
        // volume actions that belong here.
        next.remint(&mut audio_clip);
        audio_clip.track = below;
        audio_clip.enabled = Enabled {
            video: false,
            audio: true,
        };
        audio_clip.audio = target.audio.or_else(|| Some(AudioProps::default()));
        // The transition describes an overlap on the ORIGINAL track.
        audio_clip.transition_in = None;
        // The two halves name each other (spec §11 AU-90): every placement
        // edit keeps them in step from here, and Attach Audio merges them.
        audio_clip.linked = Some(clip);

        if let Some(slot) = next.clip_mut(clip) {
            slot.enabled.audio = false;
            slot.linked = Some(audio_clip.id);
        }
        self.commit_additions(next, vec![audio_clip])
    }

    // ---- enablement ------------------------------------------------------

    /// Per-clip visibility and mute (spec §6). An argument left `None` is
    /// left alone, so the two halves of Detach Audio can be set
    /// independently.
    pub fn set_enabled(
        &self,
        clip: u32,
        video: Option<bool>,
        audio: Option<bool>,
    ) -> Result<Outcome, String> {
        self.require_clip(clip)?;
        let mut next = self.clone();
        if let Some(slot) = next.clip_mut(clip) {
            if let Some(value) = video {
                slot.enabled.video = value;
            }
            if let Some(value) = audio {
                slot.enabled.audio = value;
            }
        }
        self.finish(next)
    }
}
    }
}

impl Project {
    /// Every ducking clip in the project, with the span it ducks over.
    ///
    /// Computed once per plan from the flattened timeline, so a duck set
    /// INSIDE a nest ducks over the part of it that plays, and a duck on the
    /// nest clip itself ducks over the whole nest. A clip appears at most
    /// once even when several instances name it — a nest shown twice ducks
    /// over the first span it was found at, which is a corner no UI can
    /// reach and not worth a second entry that would duck twice.
    ///
    /// The duck is read from the base props, not through actions: the ramp
    /// lengths describe an envelope, and an envelope whose own attack time
    /// animates is not a version-1 feature.
    ///
    /// A speech duck's spans are measured from the clip's ORIGIN (its first
    /// frame in project time) and kept to the part that plays, `start` to
    /// `end` (`audio_duck_speech.rs`).
    pub(crate) fn duckers(&self, instances: &[Instance<'_>]) -> Vec<Ducker> {
        let mut out: Vec<Ducker> = Vec::new();
        for instance in instances {
            // `chain`'s order, outermost first: each clip's origin beside it.
            let origins = (instance.inside.iter().map(|e| e.origin)).chain(once(instance.origin));
            for ((clip, start, end), origin) in instance.chain().zip(origins) {
                if out.iter().any(|d| d.clip == clip.id) {
                    continue;
                }
                if let Some(duck) = clip.audio.and_then(|a| a.duck) {
                    let spans = (duck.mode == DuckMode::Speech)
                        .then(|| self.speech_spans(clip, origin, (start, end), &duck));
                    out.push(Ducker {
                        clip: clip.id,
                        start,
                        end,
                        duck,
                        spans,
                    });
                }
            }
        }
        out
    }
}
    /// and `duckers` is every ducking clip in the project — this track's own
    /// are dropped here rather than by the caller.
    ///
    /// The returned ramps are in start order and tile the track's whole
    /// extent — first voice start to last voice end — with no gaps, so Swift
    /// can walk them straight into `setVolumeRamp(fromStartVolume:…)`
    /// without inventing anything in between. An empty input is an empty
    /// envelope.
    ///
    /// Folded in, in this order: the clip's `volume`; its fades; its volume
    /// actions; the same three for every nest clip it is inside; then
    /// ducking from every OTHER clip in the project whose `audio.duck` is
    /// set, multiplied over the whole thing. A clip that is silenced —
    /// `enabled.audio` false, `audio.muted`, or a track that is muted or
    /// silenced by a solo in its container, at any level — contributes 0
    /// over its extent, and so does a gap.
    pub fn audio_ramps(&self, voices: &[Voice<'_>], duckers: &[Ducker]) -> Vec<Ramp> {
        let mut own: Vec<&Voice> = voices.iter().filter(|v| v.end > v.start).collect();
        own.sort_by_key(|v| (v.start, v.clip_id()));
        let (Some(extent_start), Some(extent_end)) = (
            own.iter().map(|v| v.start).min(),
            own.iter().map(|v| v.end).max(),
        ) else {
            return Vec::new();
        };
        if extent_end <= extent_start {
            return Vec::new();
        }

        // A clip does not duck the track it plays on: ducking exists to
        // lower the OTHER material, and a segment ducking its own neighbours
        // on one composition track would be a feedback loop with no
        // user-visible cause.
        let others: Vec<&Ducker> = duckers
            .iter()
            .filter(|d| !own.iter().any(|v| v.clip_id() == d.clip))
            .collect();
        let breaks = self.breakpoints(&own, &others, extent_start, extent_end);

        let mut ramps: Vec<Ramp> = Vec::with_capacity(breaks.len());
        for pair in breaks.windows(2) {
            let (Some(&a), Some(&b)) = (pair.first(), pair.get(1)) else {
                continue;
            };
            if b <= a {
                continue;
            }
            ramps.push(Ramp {
                start: a,
                duration: b.saturating_sub(a),
                from: self.gain_at(&own, &others, a, Side::Right),
                to: self.gain_at(&own, &others, b, Side::Left),
            });
        }
        coalesce(ramps)
    }

    /// The ticks the envelope is sampled at: the ends of the extent, every
    /// voice edge, every fade edge of every stage, every duck edge, and a
    /// 1/30 s grid inside each action that touches the audio group. Sorted,
    /// deduplicated, and clipped to the extent, so the ramps built from
    /// consecutive entries tile it exactly.
    fn breakpoints(
        &self,
        voices: &[&Voice<'_>],
        duckers: &[&Ducker],
        extent_start: Ticks,
        extent_end: Ticks,
    ) -> Vec<Ticks> {
        let mut breaks: Vec<Ticks> = vec![extent_start, extent_end];

        for voice in voices {
            // The voice's own edges, which for a nested clip are the nest
            // clip's edges as much as its own.
            breaks.push(voice.start);
            breaks.push(voice.end);
            for stage in &voice.stages {
                let clip = stage.clip;
                let end = stage.origin.saturating_add(clip.duration);
                breaks.push(stage.origin);
                breaks.push(end);
                // Fades come from the base props. If an action animates a
                // fade length the action's own samples below carry the
                // change; the fade edges are only a promise that the two
                // obvious corners are breakpoints.
                let props = clip.audio.unwrap_or_default();
                if props.fade_in > 0 {
                    let edge = stage.origin.saturating_add(props.fade_in);
                    breaks.push(edge);
                    // A shaped fade is a curve, sampled like an eased action
                    // (spec §11 AU-114); its shape read where the fade runs.
            guard let media = snapshot.media(for: clip) else { return false }
            return media.hasVideo || media.kind == .image
        }
    }

    /// Whether the clip carries live audio: its media has a track AND this
    /// half of the clip is enabled (Detach Audio flips that, §6).
    ///
    /// A nest clip has no media of its own, so the media test cannot answer
    /// for it — and "no" would be the wrong answer, because a nest clip's own
    /// volume, mute and fades MULTIPLY every voice inside it
    /// (`core/src/audio.rs`: turning a nest down turns everything in it
    /// down). What it is asked instead is whether it has audio properties at
    /// all, which is the core's own answer to the same question: `nest` gives
    /// the clip an `AudioProps` exactly when something inside it can make a
    /// sound (`edit_nest.rs`) and `set_audio` errors with "clip N has no
    /// audio properties" when it did not. Walking the contents here would be
    /// a second copy of that rule, free to drift from the one the writes go
    /// through.
    static func hasAudio(_ clip: ClipSnapshot, in snapshot: ProjectSnapshot) -> Bool {
        guard clip.enabled.audio else { return false }
        if case .nest = clip.source { return clip.audio != nil }
        guard let media = snapshot.media(for: clip) else { return false }
        return media.hasAudio
    }

    /// Whether the clip's rectangle comes from a decoded source — the clips
    /// that get Crop, Colour and Corner Radius. Text and shape clips get
    /// Transform, Opacity and Shadow only (§4.3).
    static func hasSourcePixels(_ clip: ClipSnapshot, in snapshot: ProjectSnapshot) -> Bool {
        switch clip.source {
        case .media, .still, .image: return true
        case .text, .shape, .graphic, .nest, .adjustment: return false
        }
    }

    /// Whether the clip is an adjustment clip (spec §11 GR-6): it draws
    /// nothing of its own and grades what is behind it, so it gets Color and
    /// Clip and never Picture.
    static func isAdjustment(_ clip: ClipSnapshot) -> Bool {
        if case .adjustment = clip.source { return true }
        return false
    }
}

