// d08: what the core's plan answers before and after Detach Audio on a ducking clip.
use framejob_core::ffi::{rc_project_free, rc_project_from_json, rc_string_free};
use framejob_core::ffi_edit::rc_project_apply;
use framejob_core::ffi_query::rc_project_composition_plan;
use framejob_core::model::Project;
use std::ffi::{c_char, CStr, CString};
use std::ptr;

fn take(p: *mut c_char) -> Option<String> {
    if p.is_null() {
        return None;
    }
    let s = unsafe { CStr::from_ptr(p) }.to_string_lossy().into_owned();
    unsafe { rc_string_free(p) };
    Some(s)
}

fn plan(h: *const Project) -> String {
    take(unsafe { rc_project_composition_plan(h) }).unwrap()
}

fn apply(h: *const Project, op: &str) -> *mut Project {
    let c = CString::new(op).unwrap();
    let mut err = ptr::null_mut();
    let mut why = ptr::null_mut();
    let next = unsafe { rc_project_apply(h, c.as_ptr(), &mut err, &mut why) };
    if next.is_null() {
        panic!("{op}: err {:?} refused {:?}", take(err), take(why));
    }
    next
}

fn main() {
    const S: i64 = 600_000;
    let json = format!(
        r#"{{"version":1,"canvas":{{"width":1920,"height":1080,"fps":[30,1],"background":[0,0,0,1],"fit_new_clips":true,"timecode_frames":true}},
        "media":[{{"id":1,"path":"/f/1.mov","bookmark":null,"kind":"video","duration":{d},"width":1920,"height":1080,"fps":[30,1],"has_video":true,"has_audio":true}},
                 {{"id":2,"path":"/f/2.m4a","bookmark":null,"kind":"audio","duration":{d},"width":0,"height":0,"fps":[30,1],"has_video":false,"has_audio":true}}],
        "tracks":[{{"id":3,"name":"Music"}},{{"id":4,"name":"Empty"}},{{"id":5,"name":"Voice"}}],
        "clips":[{{"id":11,"track":3,"start":0,"duration":{m},"source":{{"kind":"media","media":2,"in":0}},"audio":{{}}}},
                 {{"id":12,"track":5,"start":{s5},"duration":{s5},"source":{{"kind":"media","media":1,"in":0}},"video":{{}},
                   "audio":{{"volume":1.0,"duck":{{"level":0.2,"attack":0,"release":0}}}}}}],
        "markers":[],"next_id":13}}"#,
        d = 60 * S,
        m = 20 * S,
        s5 = 5 * S
    );
    let c = CString::new(json).unwrap();
    let mut err = ptr::null_mut();
    let h0 = unsafe { rc_project_from_json(c.as_ptr(), &mut err) };
    if h0.is_null() {
        panic!("{:?}", take(err));
    }
    println!("BEFORE {}", plan(h0));

    let h1 = apply(h0, r#"{"op":"detach_audio","clip":12}"#);
    println!("DETACHED {}", plan(h1));

    // The sound half's duck switched off, which is all the Sound tab can reach.
    let h2 = apply(h1, r#"{"op":"set_audio","clips":[13],"patch":{"duck":null}}"#);
    println!("SOUNDOFF {}", plan(h2));

    // What an agent can do and a person cannot: the picture half's duck off.
    let h3 = apply(h1, r#"{"op":"set_audio","clips":[12],"patch":{"duck":null}}"#);
    println!("PICOFF {}", plan(h3));

    // Attach Audio's way back from the detached state.
    let h4 = apply(h1, r#"{"op":"attach_audio","clip":12}"#);
    println!("ATTACHED {}", plan(h4));

    for h in [h0, h1, h2, h3, h4] {
        unsafe { rc_project_free(h) };
    }
}

